<script setup lang="ts">
import { computed,ref } from 'vue'
import type { Editor } from '../lib/editor'
import { t,projectLocale } from '../lib/i18n'
import BaseButton from './base/BaseButton.vue'
const props=defineProps<{editor:Editor}>(),emit=defineEmits<{close:[];error:[message:string]}>()
const file=ref<HTMLInputElement>(),filter=ref(''),localeName=ref(''),newKey=ref('')
const config=computed(()=>props.editor.project.value.i18n!),keys=computed(()=>[...new Set(Object.values(config.value.messages).flatMap(messages=>Object.keys(messages)))].filter(key=>key.includes(filter.value)).sort())
function edit(locale:string,key:string,value:string){props.editor.mutate(()=>{config.value.messages[locale]??={};config.value.messages[locale]![key]=value})}
function addLocale(){const locale=localeName.value.trim();if(!locale)return;try{new Intl.Locale(locale)}catch{emit('error','请输入有效的语言标识，例如 zh-CN、en-US、ja-JP');return}if(config.value.locales.includes(locale))return;props.editor.mutate(()=>{config.value.locales.push(locale);config.value.messages[locale]={}});localeName.value=''}
function addKey(){const key=newKey.value.trim();if(!key||keys.value.includes(key))return;props.editor.mutate(()=>{for(const locale of config.value.locales){config.value.messages[locale]??={};config.value.messages[locale]![key]=''}});newKey.value=''}
function removeLocale(locale:string){if(config.value.locales.length<2||locale===config.value.defaultLocale)return;props.editor.mutate(()=>{config.value.locales=config.value.locales.filter(value=>value!==locale);delete config.value.messages[locale]});if(projectLocale.value===locale)projectLocale.value=config.value.defaultLocale}
function removeKey(key:string){props.editor.mutate(()=>{for(const messages of Object.values(config.value.messages))delete messages[key]})}
function download(csv=false){const body=csv?[['key',...config.value.locales],...keys.value.map(key=>[key,...config.value.locales.map(locale=>config.value.messages[locale]?.[key]??'')])].map(row=>row.map(value=>'"'+value.replaceAll('"','""')+'"').join(',')).join('\r\n'):JSON.stringify(config.value,null,2),url=URL.createObjectURL(new Blob([body],{type:csv?'text/csv;charset=utf-8':'application/json'})),a=document.createElement('a');a.href=url;a.download=`translations.${csv?'csv':'json'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvRows(text:string){const rows:string[][]=[];let row:string[]=[],value='',quoted=false;for(let index=0;index<text.length;index++){const char=text[index];if(char==='"'){if(quoted&&text[index+1]==='"'){value+='"';index++}else quoted=!quoted}else if(char===','&&!quoted){row.push(value);value=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[index+1]==='\n')index++;row.push(value);rows.push(row);row=[];value=''}else value+=char}if(quoted)throw Error('CSV 引号未闭合');if(value||row.length){row.push(value);rows.push(row)}return rows}
async function importFile(event:Event){const input=event.target as HTMLInputElement,source=input.files?.[0];if(!source)return;try{const text=(await source.text()).replace(/^\uFEFF/,''),next=source.name.endsWith('.csv')?(()=>{const rows=csvRows(text),header=rows.shift();if(header?.[0]!=='key'||header.length<2)throw Error('CSV 第一列必须为 key，其余列为语言标识');const locales=header.slice(1),messages:Record<string,Record<string,string>>=Object.fromEntries(locales.map(locale=>[locale,{}]));for(const row of rows)if(row[0])for(const [index,locale]of locales.entries())messages[locale]![row[0]]=row[index+1]??'';return{locales,messages}})():JSON.parse(text);if(!Array.isArray(next.locales)||!next.messages)throw Error('翻译文件需要 locales 和 messages');for(const locale of next.locales){new Intl.Locale(locale);if(!next.messages[locale]||Object.values(next.messages[locale]).some(value=>typeof value!=='string'))throw Error('翻译词条必须是文本')}props.editor.mutate(()=>{for(const locale of next.locales){if(!config.value.locales.includes(locale))config.value.locales.push(locale);config.value.messages[locale]={...config.value.messages[locale],...next.messages[locale]}}})}catch(error){emit('error',String(error))}finally{input.value=''}}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="language-dialog" role="dialog" aria-modal="true" :aria-label="t('工程语言')"><header><h2>{{ t('工程语言') }}</h2><button class="icon-button" title="关闭" @click="emit('close')">×</button></header><div class="language-toolbar"><label>{{ t('默认语言') }}<select :value="config.defaultLocale" @change="editor.mutate(()=>config.defaultLocale=($event.target as HTMLSelectElement).value)"><option v-for="locale in config.locales" :key="locale">{{ locale }}</option></select></label><label>{{ t('预览语言') }}<select v-model="projectLocale"><option v-for="locale in config.locales" :key="locale">{{ locale }}</option></select></label><input v-model="localeName" placeholder="en-US / ja-JP" aria-label="新增语言"/><BaseButton @click="addLocale">{{ t('新增语言') }}</BaseButton><BaseButton @click="file?.click()">{{ t('导入翻译') }}</BaseButton><BaseButton @click="download()">JSON</BaseButton><BaseButton @click="download(true)">CSV</BaseButton></div><div class="translation-filter"><input v-model="filter" placeholder="搜索词条…"/><input v-model="newKey" placeholder="widget.title" @keydown.enter="addKey"/><BaseButton @click="addKey">{{ t('新增词条') }}</BaseButton></div><div class="translation-table"><table><thead><tr><th>{{ t('词条') }}</th><th v-for="locale in config.locales" :key="locale">{{ locale }}<button v-if="locale!==config.defaultLocale" title="移除语言" @click="removeLocale(locale)">×</button></th><th/></tr></thead><tbody><tr v-for="key in keys" :key="key"><td><code>{{ key }}</code></td><td v-for="locale in config.locales" :key="locale"><textarea rows="2" :aria-label="`${key} ${locale}`" :value="config.messages[locale]?.[key]??''" :class="{missing:!config.messages[locale]?.[key]}" @change="edit(locale,key,($event.target as HTMLTextAreaElement).value)"/></td><td><button title="删除词条" @click="removeKey(key)">×</button></td></tr></tbody></table><p v-if="!keys.length">{{ t('新增词条后，可在组件属性中选择翻译键。') }}</p></div><footer>{{ t('缺失翻译使用默认语言及原始文本；翻译随工程包保存。') }}</footer><input ref="file" type="file" accept=".json,.csv" hidden @change="importFile"/></section></div></template>
<style scoped>.language-dialog{background:white;width:min(1100px,95vw);height:min(760px,90dvh);border-radius:10px;display:flex;flex-direction:column;min-height:0;padding:20px;gap:14px;box-shadow:0 15px 60px #132c4440}.language-dialog header{display:flex;justify-content:space-between;align-items:center}.language-dialog h2{font-size:18px}.language-toolbar,.translation-filter{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.language-toolbar label{width:130px;margin:0}.language-toolbar>input{width:130px}.translation-filter>input{width:230px}.translation-table{flex:1;min-height:0;overflow:auto}.translation-table table{border-collapse:collapse;width:100%;font-size:12px}.translation-table th{position:sticky;top:0;background:#f3f6fa;z-index:1}.translation-table th,.translation-table td{text-align:left;padding:8px;border:1px solid #e1e6ed;min-width:180px}.translation-table th:last-child,.translation-table td:last-child{min-width:30px}.translation-table textarea{resize:vertical;min-height:42px}.translation-table textarea.missing{border-color:#d8a04c}.language-dialog footer{font-size:11px;color:#788390}.translation-table p{padding:30px}</style>
